"""CPU regression against immutable outputs generated by qlean 0.2.0."""

import hashlib
import json
from pathlib import Path

import pytest

torch = pytest.importorskip("torch")

from tests.quantization.online.online_quantization_golden_inputs import (  # noqa: E402
    cases,
    tensor_digest,
)
from vllm_sail.model_executor.layers.quantization.online_quantization.quant_utils import (  # noqa: E402
    dequantize_fp8,
    quantize_int8,
)

GOLDEN = Path(__file__).with_name("online_quantization_qlean_golden.json")


def test_online_quantization_matches_qlean_golden():
    reference = json.loads(GOLDEN.read_text())
    assert reference["schema_version"] == 1
    assert reference["qlean_version"] == "0.2.0+v0.1.0.ppu2.1.0"
    recipe = Path(__file__).with_name("online_quantization_golden_inputs.py")
    assert (
        reference["input_recipe_sha256"]
        == hashlib.sha256(recipe.read_bytes()).hexdigest()
    )
    expected = reference["tensors"]
    actual = {}
    for name, source, weight, scales in cases():
        decoded = dequantize_fp8(weight, scales) if source == "fp8" else weight
        if source == "fp8":
            actual[f"{name}.fp8_to_bf16.weight"] = tensor_digest(decoded)
        q, s = quantize_int8(decoded)
        route = "fp8_to_int8" if source == "fp8" else "bf16_to_int8"
        actual[f"{name}.{route}.weight"] = tensor_digest(q)
        actual[f"{name}.{route}.weight_scale"] = tensor_digest(s)
    assert set(actual) == set(expected)
    for name, result in actual.items():
        assert result == expected[name], f"qlean golden differs for {name}: {result}"
